import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates().reset_index(drop=True)
    if 'Category' in df.columns:
        cat = df['Category'].astype('string').str.strip()
        cat_map = {'electronics': 'Electronics', 'accessories': 'Accessories', 'furniture': 'Furniture', 'office supplies': 'Office Supplies'}
        df['Category'] = cat.str.lower().map(cat_map).fillna(cat)
    if 'Region' in df.columns:
        reg = df['Region'].astype('string').str.strip()
        reg_map = {'north': 'North', 'south': 'South', 'east': 'East', 'west': 'West', 'suoth': 'South', 'eats': 'East'}
        df['Region'] = reg.str.lower().map(reg_map).fillna(reg)
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category'])
    counts = d.groupby('Category')['Order_ID'].nunique()
    return {str(k): int(v) for k, v in counts.items()}
